if(action==='diagnostics'){const d=await api('/api/hub/diagnostics');$('#settings-status').innerHTML=`<p class="${d.fn_error?'error':'muted'}">${esc(d.fn_error||(d.fn_code===0?'飞牛连接正常':'飞牛返回状态 '+d.fn_code))} · 已核对挂载文件 ${num(d.mapped_files)} 首</p><p class="muted">归音工作线程：${d.worker?'运行中':'已停止'} · 目录音乐 ${num(d.library.count)} 首</p>`;}
