async function boot(){page=titles[location.hash.slice(1)]?location.hash.slice(1):'overview';try{const d=await api('/api/session');logged=!!d.authenticated;csrf=d.csrf||'';$('#login-overlay').classList.toggle('hidden',logged);await showPage(page)}catch(e){toast(e.message)}}
let refreshBusy=false;setInterval(async()=>{if(!logged||refreshBusy||document.querySelector('dialog[open]'))return;refreshBusy=true;try{if(page==='downloads')await loadJobs();if(page==='library')await loadLibrary();if(page==='assets')await loadAssets();if(page==='overview')await overview();if(!['overview','downloads'].includes(page))queueBadge(await api('/api/hub/stats'));}catch{}finally{refreshBusy=false}},15000);
window.addEventListener('DOMContentLoaded',boot,{once:true});

window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(titles[next]&&next!==page)showPage(next)});


let enhancedMusicTab=null;
function openMusicTab(){
  if(enhancedMusicTab && !enhancedMusicTab.closed){enhancedMusicTab.focus();return;}
  enhancedMusicTab=window.open('','guiyin-fnmusic-enhanced');
  if(!enhancedMusicTab){toast('请允许归音打开新标签页，再点击音乐台');return;}
  try{if(enhancedMusicTab.location.href==='about:blank')enhancedMusicTab.location.replace('/music/');}catch(e){}
  enhancedMusicTab.focus();
}
async function browseFusionDirectory(path){
 const d=await api('/api/hub/directories?path='+encodeURIComponent(path));
 const el=$('#fusion-directory-browser');if(!el)return;
 el.innerHTML=`<div class="panel-head"><strong>${esc(d.path)}</strong><button type="button" data-action="fusion-dir-select" data-path="${esc(d.path)}">选择此目录</button></div>${d.parent?`<button type="button" data-action="fusion-dir-browse" data-path="${esc(d.parent)}">↑ 上级</button>`:''}<div class="directory-list">${d.directories.map(x=>`<button type="button" data-action="fusion-dir-browse" data-path="${esc(x.path)}">▱ ${esc(x.name)}</button>`).join('')||'<p class="muted">无子目录，可在保存目录中填写新文件夹名称。</p>'}</div>`;
}

let assetOffset=0,assetDirectoryId='',assetSelectedDirs=new Set();
async function loadAssets(){
 const r=await api('/api/hub/asset-directories?key='+encodeURIComponent(assetDirectoryId)+'&offset='+assetOffset);
 $('#asset-content').innerHTML=`<article class="panel settings-panel"><div class="panel-head"><div><h3>按目录同步歌词与封面</h3><p class="muted">可添加多个目录，包含子目录。新目录默认暂停；继续后自动扫描并补全，每轮完成后约 5 分钟再次检查本地文件。多个目录分批轮流匹配。这里统计已保存到目录的音频文件，尚未下载的歌曲会在文件落盘后纳入扫描。</p></div><button class="primary" data-action="asset-dirs-add">＋ 添加目录</button></div><p class="muted">歌词与封面保存在音乐旁，使用相同文件名；已有内容不覆盖。只匹配歌名、歌手与时长相符的资源。按设置中启用音源的优先级尝试；歌词和封面可分别由不同源补全。仅支持音频的 JS 源会跳过。</p>${r.directories.map(x=>{const skipped=Math.max(0,x.scanned-x.total);const finished=!x.running&&!x.error&&x.phase==='本轮完成，等待检查新增文件';const pct=x.total?Math.floor(x.processed*100/x.total):finished?100:0;return `<article class="comment-directory-card"><div class="panel-head"><div><strong>${esc(x.path)}</strong><small>${!x.enabled?'已暂停':x.running?esc(x.phase):finished?'本轮检查完成 · 等待下一轮扫描':x.phase==='等待继续匹配'?'等待继续匹配':'等待扫描'}${!x.enabled&&x.running?' · 正在停止当前请求':''}</small></div><div class="button-row"><button data-action="asset-dir-control" data-id="${esc(x.id)}" data-control="${x.enabled?'pause':'resume'}" class="${x.enabled?'':'primary'}">${x.enabled?'暂停同步':'继续同步'}</button><button data-action="asset-dir-control" data-id="${esc(x.id)}" data-control="scan" ${x.running||!x.enabled?'disabled':''}>立即扫描</button><button data-action="asset-dir-details" data-id="${esc(x.id)}">查看明细</button><button data-action="asset-dir-remove" data-id="${esc(x.id)}">移除目录</button></div></div><p>已扫描 ${num(x.scanned)} 首本地音频 · 已有信息，已跳过 ${num(skipped)} 首 · 本轮已处理 ${num(x.processed)} / ${num(x.total)} 项 · 已补全 ${num(x.completed)} · 未完全匹配 ${num(x.unmatched)}</p><progress max="100" value="${pct}" aria-label="${esc(x.path)} 歌词封面匹配进度"></progress>${x.current?`<small>正在匹配：${esc(x.current)}</small>`:''}${x.error?`<p class="error">${esc(x.error)}</p>`:''}</article>`}).join('')||'<p class="muted">请添加需要同步的音乐目录。</p>'}</article>${assetDirectoryId?`<article class="panel table-panel"><h3>${esc(r.directories.find(x=>x.id===assetDirectoryId)?.path||'目录明细')}</h3><table><thead><tr><th>音乐 / 路径</th><th>缺失项目</th><th>状态 / 来源</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td><strong>${esc(x.title)}</strong><small>${esc(x.artists.join(' / '))}</small><small>${esc(x.path)}</small></td><td>${[x.lyric_missing?'歌词':'',x.cover_missing?'封面':''].filter(Boolean).join('、')||'—'}</td><td>${esc(x.status)}<small>${esc(x.detail||'')}</small></td></tr>`).join('')||`<tr><td colspan="3">${(()=>{const d=r.directories.find(x=>x.id===assetDirectoryId);return d&&d.scanned>0&&!d.error&&d.phase==='本轮完成，等待检查新增文件'?`已检查 ${num(d.scanned)} 首，歌词与封面已有信息，已跳过。`:'尚未扫描或没有缺失项目。'})()}</td></tr>`}</tbody></table><div class="button-row"><button data-action="asset-prev" ${assetOffset?'':'disabled'}>上一页</button><span>第 ${r.total?Math.floor(assetOffset/100)+1:0} / ${Math.ceil(r.total/100)} 页 · 共 ${num(r.total)} 项</span><button data-action="asset-next" ${assetOffset+100<r.total?'':'disabled'}>下一页</button></div></article>`:''}`;
}
function renderAssetChoices(){$('#asset-directory-choices').innerHTML=[...assetSelectedDirs].map(p=>`<div class="panel-head"><span>${esc(p)}</span><button type="button" data-action="asset-dir-unselect" data-path="${esc(p)}">取消选择</button></div>`).join('');}
async function assetDirectoryDialog(){assetSelectedDirs=new Set();modal('添加歌词与封面同步目录',`<form id="asset-directories-form"><p class="muted">可选择多个目录，添加后默认暂停。</p><div id="asset-directory-choices" class="choice-list"></div><div id="asset-directory-browser" class="directory-browser"></div><button class="primary">添加所选目录</button></form>`);const s=await api('/api/hub/settings');await browseAssetDirectory(s.mount_root);}
async function browseAssetDirectory(path){const d=await api('/api/hub/directories?path='+encodeURIComponent(path));$('#asset-directory-browser').innerHTML=`<div class="panel-head"><strong>${esc(d.path)}</strong><button type="button" data-action="asset-dir-select" data-path="${esc(d.path)}">选择此目录</button></div>${d.parent?`<button type="button" data-action="asset-dir-browse" data-path="${esc(d.parent)}">↑ 上级</button>`:''}<div class="directory-list">${d.directories.map(x=>`<button type="button" data-action="asset-dir-browse" data-path="${esc(x.path)}">▱ ${esc(x.name)}</button>`).join('')||'<p class="muted">无子目录</p>'}</div>`;}
let assetRefreshBusy=false;setInterval(async()=>{if(!logged||page!=='assets'||assetRefreshBusy||document.querySelector('dialog[open]'))return;assetRefreshBusy=true;try{await loadAssets()}catch{}finally{assetRefreshBusy=false}},3000);

let sourceRows=[],sourceOrderBusy=false;
async function loadSources(){const r=await api('/api/hub/sources');sourceRows=r.sources;$('#source-list').innerHTML=sourceRows.map((s,index)=>`<div class="source-row"><div><strong>${esc(s.name)}</strong><small>${s.platforms.map(p=>esc(names[p]||p)).join(' / ')} · ${s.kind==='lx'?'LX JS '+esc(s.version||''):s.kind==='http'?'自定义':s.kind==='legacy'?'保留的原有配置':'项目内置'} · ${s.enabled?'已启用':'已停用'}${s.token_configured?' · 已配置令牌':''}</small>${s.url?`<small class="source-url">${esc(s.url)}</small>`:''}${s.note?`<small>${esc(s.note)}</small>`:''}<small id="source-result-${esc(s.id)}" role="status"></small></div><div class="button-row"><label class="source-priority-label">优先级<select class="source-priority" data-id="${esc(s.id)}" aria-label="${esc(s.name)}的使用优先级">${sourceRows.map((_,i)=>`<option value="${i+1}" ${i===index?'selected':''}>${i+1}${i===0?' · 最先尝试':''}</option>`).join('')}</select></label>${s.kind==='http'?`<button data-action="source-edit" data-id="${esc(s.id)}">编辑</button>`:''}${s.kind==='lx'?`<a class="button" href="/api/hub/sources/${encodeURIComponent(s.id)}/script" download="${esc(s.filename)}">下载 JS</a>`:''}<button data-action="source-test" data-id="${esc(s.id)}">测试</button><button data-action="source-toggle" data-id="${esc(s.id)}">${s.enabled?'停用':'启用'}</button></div></div>`).join('');}

async function moveSourcePriority(id,position){
 if(sourceOrderBusy)return;
 const ids=sourceRows.map(row=>row.id),from=ids.indexOf(id),to=Number(position)-1;
 if(from<0||!Number.isInteger(to)||to<0||to>=ids.length||from===to)return;
 ids.splice(from,1);ids.splice(to,0,id);
 sourceOrderBusy=true;$$('.source-priority').forEach(el=>el.disabled=true);
 try{await api('/api/hub/sources/order','PUT',{ids});await loadSources();toast('音源优先级已保存，后续下载与重试按此顺序尝试');}
 catch(e){toast(e.message);await loadSources();}
 finally{sourceOrderBusy=false;$$('.source-priority').forEach(el=>el.disabled=false);}
}
document.addEventListener('change',e=>{if(e.target.matches('.source-priority'))moveSourcePriority(e.target.dataset.id,e.target.value).catch(e=>toast(e.message));});
function sourceDialog(id){const s=sourceRows.find(x=>x.id===id)||{name:'',url:'',platforms:[],enabled:true};modal(id?'编辑音源':'添加音源',`<form id="source-form"><input type="hidden" name="id" value="${esc(id||'')}"><label>名称<input name="name" value="${esc(s.name)}" maxlength="100" required></label><label>解析接口（HTTP POST）<input name="url" type="url" value="${esc(s.url)}" placeholder="https://你的服务器/resolve" required maxlength="2000"></label><div class="form-checks">${Object.entries(names).map(([p,n])=>`<label><input type="checkbox" name="platform" value="${p}" ${s.platforms.includes(p)?'checked':''}> ${n}</label>`).join('')}</div><label>接口令牌（可选）<input name="token" type="password" autocomplete="new-password" maxlength="4000" placeholder="${s.token_configured?'已配置，留空保留':'仅发送给该接口'}"></label>${s.token_configured?'<label class="check"><input type="checkbox" name="clear_token">清除已保存令牌</label>':''}<label class="check"><input name="enabled" type="checkbox" ${s.enabled?'checked':''}>启用此音源</label><p class="muted">此表单添加 HTTP 接口；JS 音源请使用“导入 JS / JSON”。平台账号凭据不会发送到自定义接口。</p><p class="form-status error" hidden role="status"></p><button class="primary">保存音源</button></form>`);}
function sourceHelp(){modal('音源接口格式',`<p>导入 JSON 文件可包含多个 HTTP 音源。请求使用 POST，字段为 platform、id、quality、title、artists、duration_ms。可选令牌以 Authorization: Bearer 发送；接口不接受重定向。</p><p>响应必须返回相同 platform / id、preview: false、实际 quality 和 duration_ms，以及公网音频 url。可选 lyric、cover_url。用于歌词封面匹配时，请求另带 action: assets；响应只需相同 platform / id 及 lyric、cover_url，无需音频地址。JS 文件支持 LX Music 的 lx.on(request) / lx.send(inited) 接口，也支持声明的 lyric / pic 动作；MusicFree 的 module.exports 插件不兼容，会提示原因。JS 在独立进程中运行，只能访问公网接口，不读取账号、文件和环境变量。</p><pre>${esc(JSON.stringify({version:1,sources:[{kind:'http',name:'我的音源',url:'https://example.com/resolve',platforms:['netease','qq'],enabled:true}]},null,2))}</pre><p>响应示例（地址为占位）：</p><pre>${esc(JSON.stringify({platform:'qq',id:'请求的歌曲ID',url:'https://example.com/audio.mp3',quality:'standard',duration_ms:200000,preview:false},null,2))}</pre>`);}
async function importSourceFiles(files){
 const results=[];let added=0;
 for(const f of files){
  try{
   if(f.size>262144)throw Error('文件最多 256 KB');
   const content=(await f.text()).replace(/^\uFEFF/,'');
   let r;
   if(/\.js$/i.test(f.name))r=await api('/api/hub/sources/import-js','POST',{filename:f.name,code:content});
   else if(/\.json$/i.test(f.name))r=await api('/api/hub/sources/import','POST',JSON.parse(content));
   else throw Error('请选择 JS 或 JSON 文件');
   added+=r.added;results.push(`${f.name}：${r.added?'已导入，可点击测试':r.repaired?'文件已修复，保留原配置，可重新测试':'已存在，保留原配置'}`);
  }catch(error){results.push(`${f.name}：导入失败，${error.message}`);}
 }
 await loadSources();$('#source-import-result').textContent=results.join('；');toast(`已添加 ${added} 个音源`);
 return results;
}
$('#source-file').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;const b=$('[data-action="source-import"]');b.disabled=true;$('#source-import-result').textContent='正在识别音源文件…';try{await importSourceFiles(files)}finally{e.target.value='';b.disabled=false}};

