function commentTime(s){return s==null?'待估算':s<60?Math.ceil(s)+' 秒':Math.ceil(s/60)+' 分钟';}
async function loadCommentDirectories(){
 const [d,overall]=await Promise.all([api('/api/hub/comment-directories'),api('/api/comments/progress')]),el=$('#comment-directory-list');if(!el)return;
 const metrics=$('#comment-metrics'),run=overall.run_progress;if(metrics)metrics.innerHTML=metric('评论',num(overall.comments_total),'本地已保存')+metric('覆盖歌曲',num(overall.covered_songs),'/ '+num(overall.total_songs)+' 首')+metric('覆盖率',Number(overall.coverage_percent||0).toFixed(1)+'%','当前飞牛曲库')+metric('本轮进度',num(run?.done)+' / '+num(run?.total),'按歌曲计数');
 const live=$('#comment-live-status');if(live&&run)live.textContent=(run.status==='running'?'正在采集：':run.status==='queued'?'等待采集：':'最近一轮：')+(run.song_name||'')+' · 已处理 '+num(run.done)+' / '+num(run.total)+' 首 · 新增 '+num(run.rows_new)+' 条 · 已用 '+commentTime(run.elapsed_s)+' · 预计剩余 '+commentTime(['running','queued'].includes(run.status)?run.eta_s:0);
 el.innerHTML=d.directories.map(x=>{
  const p=x.progress||{},state=x.scanning?'扫描目录中':!x.enabled?'已暂停':x.running?'采集中':x.failed?'等待重试':x.total&&x.done===x.total?'本轮完成':'等待采集';
  const checkpoint=Number(x.completed_inflight||0),done=Math.min(x.total,x.done+checkpoint),percent=x.total?Math.round(done*1000/x.total)/10:0;
  return `<article class="comment-directory-card"><div class="panel-head"><div><strong>${esc(x.path)}</strong><small>${state}${!x.enabled&&x.running?' · 正在停止本批':''}</small></div><div class="button-row"><button data-action="comment-dir-control" data-id="${esc(x.id)}" data-control="${x.enabled?'pause':'resume'}" class="${x.enabled?'':'primary'}">${x.enabled?'暂停同步':'继续同步'}</button><button data-action="comment-dir-control" data-id="${esc(x.id)}" data-control="scan" ${x.scanning?'disabled':''}>立即扫描</button><button data-action="comment-dir-remove" data-id="${esc(x.id)}">移除目录</button></div></div><div class="panel-head"><span>已完成 ${num(done)} / ${num(x.total)} 首</span><strong>${percent}%</strong></div><progress max="100" value="${percent}" aria-label="${esc(x.path)} 评论同步进度"></progress><small>待采集 ${num(x.pending)} · 处理中 ${num(Math.max(0,x.running-checkpoint))} · 待重试 ${num(x.failed)} · 完成表示已达目标或来源评论已采完</small>${x.running?`<p class="muted">${esc(p.song_name||'正在准备本批歌曲')}${p.source?' · '+esc(names[p.source]||p.source):''}<br>本批已处理 ${num(p.done)} / ${num(p.total)} 首 · 新增 ${num(p.rows_new)} 条 · 已用 ${commentTime(p.elapsed_s)} · 本批剩余 ${commentTime(p.eta_s)}</p>`:''}${x.error||x.detail?`<p class="error">${esc(x.error||x.detail)}</p>`:''}</article>`;
 }).join('')||'<p class="muted">尚未添加目录。选择文件夹后，可分别控制评论同步。</p>';
}
function renderCommentChoices(){$('#comment-directory-choices').innerHTML=[...commentSelectedDirs].map(p=>`<div class="panel-head"><span>${esc(p)}</span><button type="button" data-action="comment-dir-unselect" data-path="${esc(p)}">取消选择</button></div>`).join('');}
async function commentDirectoryDialog(){commentSelectedDirs=new Set();modal('添加评论同步目录',`<form id="comment-directories-form"><p class="muted">可以选择多个目录；只读取音频标签，不修改音乐文件。</p><div id="comment-directory-choices" class="choice-list"></div><div id="comment-directory-browser" class="directory-browser"></div><button class="primary">添加所选目录</button></form>`);const s=await api('/api/hub/settings');await browseCommentDirectory(s.mount_root);}
async function browseCommentDirectory(path){const d=await api('/api/hub/directories?path='+encodeURIComponent(path));$('#comment-directory-browser').innerHTML=`<div class="panel-head"><strong>${esc(d.path)}</strong><button type="button" data-action="comment-dir-select" data-path="${esc(d.path)}">选择此目录</button></div>${d.parent?`<button type="button" data-action="comment-dir-browse" data-path="${esc(d.parent)}">↑ 上级</button>`:''}<div class="directory-list">${d.directories.map(x=>`<button type="button" data-action="comment-dir-browse" data-path="${esc(x.path)}">▱ ${esc(x.name)}</button>`).join('')||'<p class="muted">无子目录</p>'}</div>`;}
setInterval(async()=>{if(!logged||page!=='comments'||commentProgressBusy||document.querySelector('dialog[open]'))return;commentProgressBusy=true;try{await loadCommentDirectories()}catch{}finally{commentProgressBusy=false}},3000);

let metadataKey='',metadataOffset=0,metadataDirs=new Set(),metadataBusy=false;
async function loadMetadata(){
 const r=await api('/api/hub/metadata-directories?key='+encodeURIComponent(metadataKey)+'&offset='+metadataOffset);
 $('#metadata-content').innerHTML=`<article class="panel settings-panel"><div class="panel-head"><div><h3>按目录检查歌曲信息</h3><p class="muted">目录默认暂停。开始后逐首核对，之后每天检查一次；可随时暂停或立即检查。</p></div><button class="primary" data-meta="add">＋ 添加目录</button></div><p class="muted">自动修复专辑与发行年份：歌名、全部歌手和时长必须相符，至少两个平台一致，且其他匹配版本没有冲突。歌名或歌手本身不可靠时保留原值，不凭文件名猜测。完整日期不会被降为年份。只更新标签，不转码、不改文件名；每次修改保留原文件备份，可在下方撤销。</p>${r.directories.map(x=>`<article class="comment-directory-card"><div class="panel-head"><strong>${esc(x.path)}</strong><div class="button-row"><button data-meta="control" data-id="${esc(x.id)}" data-control="${x.enabled?'pause':'resume'}">${x.enabled?'暂停检查':'开始检查并修复'}</button><button data-meta="control" data-id="${esc(x.id)}" data-control="scan">立即检查</button><button data-meta="details" data-id="${esc(x.id)}">查看明细</button><button data-meta="remove" data-id="${esc(x.id)}">移除目录</button></div></div><p>${!x.enabled?'已暂停':x.running?esc(x.phase):'等待下一轮'} · 已扫描 ${num(x.scanned)} · 已处理 ${num(x.processed)} / ${num(x.total)} · 已修复 ${num(x.completed)} · 未修改 ${num(x.unmatched)}</p><progress max="${x.total||1}" value="${x.processed}"></progress>${x.current?`<small>正在核对：${esc(x.current)}</small>`:''}${x.error?`<p class="error">${esc(x.error)}</p>`:''}</article>`).join('')||'<p class="muted">添加需要检查的目录后，点击开始检查并修复。</p>'}</article>${metadataKey?`<article class="panel table-panel"><table><thead><tr><th>音乐 / 路径</th><th>状态 / 修改说明</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td><strong>${esc(x.title)}</strong><small>${esc(x.artists?.join(' / '))}</small><small>${esc(x.path)}</small></td><td>${esc(x.status)}<small>${esc(x.detail||'')}</small></td></tr>`).join('')}</tbody></table><div class="button-row"><button data-meta="prev" ${metadataOffset?'':'disabled'}>上一页</button><span>第 ${r.total?Math.floor(metadataOffset/100)+1:0} / ${Math.ceil(r.total/100)} 页 · 共 ${num(r.total)} 首</span><button data-meta="next" ${metadataOffset+100<r.total?'':'disabled'}>下一页</button></div></article>`:''}<article class="panel table-panel"><h3>最近修改记录</h3><p class="muted">备份保存在归音数据卷 metadata-backups 中。撤销后保留备份，并停止对该原文件重复应用修复；文件又被修改过时不会强行覆盖。</p><table><thead><tr><th>文件</th><th>修改前 → 修改后 / 证据</th><th>操作</th></tr></thead><tbody>${r.history.map(x=>{const before=JSON.parse(x.before_tags),after=JSON.parse(x.after_tags),proof=JSON.parse(x.proof);return `<tr><td>${esc(x.path)}<small>${when(x.created)}</small></td><td>${Object.entries(after).map(([k,v])=>`${esc({album:'专辑',date:'发行年份'}[k]||k)}：${esc(before[k]?.join(' / ')||'空')} → ${esc(v.join(' / '))}<small>${esc((proof[k]||[]).map(p=>names[p]||p).join('、'))}</small>`).join('')}</td><td>${x.restored?'已撤销':`<button data-meta="restore" data-id="${esc(x.id)}">撤销修改</button>`}</td></tr>`}).join('')||'<tr><td colspan="3">尚无修改记录。</td></tr>'}</tbody></table></article>`;
}
async function metadataBrowse(path){const d=await api('/api/hub/directories?path='+encodeURIComponent(path));$('#metadata-browser').innerHTML=`<div class="panel-head"><strong>${esc(d.path)}</strong><button type="button" data-meta="select" data-path="${esc(d.path)}">选择此目录</button></div>${d.parent?`<button type="button" data-meta="browse" data-path="${esc(d.parent)}">↑ 上级</button>`:''}<div class="directory-list">${d.directories.map(x=>`<button type="button" data-meta="browse" data-path="${esc(x.path)}">▱ ${esc(x.name)}</button>`).join('')}</div>`;}
function metadataChoices(){$('#metadata-choices').innerHTML=[...metadataDirs].map(p=>`<div class="panel-head"><span>${esc(p)}</span><button type="button" data-meta="unselect" data-path="${esc(p)}">取消选择</button></div>`).join('');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-meta]');if(!b)return;b.disabled=true;try{
 const a=b.dataset.meta;
 if(a==='add'){metadataDirs=new Set();modal('添加歌曲信息检查目录','<div id="metadata-choices"></div><div id="metadata-browser" class="directory-browser"></div><button class="primary" data-meta="save-dirs">添加所选目录</button>');await metadataBrowse((await api('/api/hub/settings')).mount_root);}
 if(a==='browse')await metadataBrowse(b.dataset.path);
 if(a==='select'||a==='unselect'){a==='select'?metadataDirs.add(b.dataset.path):metadataDirs.delete(b.dataset.path);metadataChoices();}
 if(a==='save-dirs'){if(!metadataDirs.size)throw Error('请先选择目录');for(const path of metadataDirs)await api('/api/hub/metadata-directories','POST',{path});closeModal();await loadMetadata();toast('目录已添加，默认暂停');}
 if(a==='control'){await api('/api/hub/metadata-directories/'+encodeURIComponent(b.dataset.id),'POST',{action:b.dataset.control});await loadMetadata();}
 if(a==='remove'&&confirm('移除此检查目录？音乐文件、修改记录和备份会保留。')){await api('/api/hub/metadata-directories/'+encodeURIComponent(b.dataset.id),'DELETE');if(metadataKey===b.dataset.id){metadataKey='';metadataOffset=0;}await loadMetadata();toast('目录已移除');}
 if(a==='details'){metadataKey=b.dataset.id;metadataOffset=0;await loadMetadata();}
 if(a==='prev'||a==='next'){metadataOffset=Math.max(0,metadataOffset+(a==='next'?100:-100));await loadMetadata();}
 if(a==='restore'){await api('/api/hub/metadata-restore/'+encodeURIComponent(b.dataset.id),'POST');await loadMetadata();toast('已恢复修改前的文件');}
}catch(err){toast(err.message)}finally{b.disabled=false}});
setInterval(async()=>{if(!logged||page!=='metadata'||metadataBusy||document.querySelector('dialog[open]'))return;metadataBusy=true;try{await loadMetadata()}catch{}finally{metadataBusy=false}},3000);
